  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    if (req.method === 'POST') {
      res.statusCode = 201
      res.setHeader('location', `http://localhost:${server.address().port}/target`)
      res.setHeader('content-location', '/other-target')
      res.end('created')
      return
    }

    requestsToOrigin++
    res.setHeader('cache-control', 's-maxage=10')
    res.end('asd')
  }).listen(0)

  after(() => server.close())
  await once(server, 'listening')

  const origin = `http://localhost:${server.address().port}`
  const client = new Client(origin)
    .compose(interceptors.cache({ store: new MemoryCacheStore() }))
  after(async () => await client.close())

  // Cache both targets
  await (await client.request({ origin, method: 'GET', path: '/target' })).body.dump()
  await (await client.request({ origin, method: 'GET', path: '/other-target' })).body.dump()
  equal(requestsToOrigin, 2)

  // Sanity check, both are served from the cache
  await (await client.request({ origin, method: 'GET', path: '/target' })).body.dump()
  await (await client.request({ origin, method: 'GET', path: '/other-target' })).body.dump()
  equal(requestsToOrigin, 2)

  await (await client.request({ origin, method: 'POST', path: '/src' })).body.dump()

  // Both targets should have been invalidated and refetched
  await (await client.request({ origin, method: 'GET', path: '/target' })).body.dump()
  equal(requestsToOrigin, 3)

  await (await client.request({ origin, method: 'GET', path: '/other-target' })).body.dump()
  equal(requestsToOrigin, 4)
})

test('unsafe methods don\'t purge cross-origin location uris', async () => {
  const store = new MemoryCacheStore()
  const deletedKeys = []
  const originalDelete = store.delete.bind(store)
  store.delete = (key) => {
    deletedKeys.push(key)
    originalDelete(key)
  }

  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    if (req.method === 'POST') {
      res.statusCode = 303
      res.setHeader('location', 'http://example.com/target')
      res.end('')
      return
    }

    res.setHeader('cache-control', 's-maxage=10')
    res.end('asd')
  }).listen(0)

  after(() => server.close())
  await once(server, 'listening')

  const origin = `http://localhost:${server.address().port}`
  const client = new Client(origin).compose(interceptors.cache({ store }))
  after(async () => await client.close())

  await (await client.request({ origin, method: 'POST', path: '/src' })).body.dump()

  equal(deletedKeys.length, 1)
  equal(deletedKeys[0].path, '/src')
})

